window.CNA=[{"ch":2,"bp":["Egzamen ekri MA: Wòl ak responsablite (9 kesyon sou 60) ak Kominikasyon (5).","MA written exam: Role and Responsibility (9 of 60 questions) and Communication (5)."],"title":["Wòl ou nan yon mezon retrèt","Your role in a nursing home"],"src":["S1","S21","S22","S28","S29","S25","S26","S27","S24"],"sections":[{"h":["Lè w aksepte yon travay","Taking on a task"],"src":["S1","S28","S29"],"b":[["p","Yon enfimyè (RN) ka ba w anpil travay pou w fè. Chak travay dwe klè, epi yon moun dwe sipèvize l.","A registered nurse (RN) can assign or delegate many tasks to you. Each task must be clear and supervised."],["li","Anvan w aksepte yon travay, tcheke 4 «S» yo: Scope (limit travay ou), Supervision (siveyans), Safety (sekirite) ak Supplies (materyèl).","Before you accept a task, check the 4 S's: Scope, Supervision, Safety and Supplies."],["li","Pa fè yon konpetans ou pa t aprann. Menm yon konpetans ou te konn fè ka bezwen fòmasyon ankò, tankou yon leve mekanik.","Do not do a skill you were not trained for. Even a skill you learned before may need retraining, for example a mechanical lift."],["li","Si w pa gen bon materyèl la, travay la pa an sekirite. Si w pa sèten, mande enfimyè a.","If you do not have the right equipment, the task is not safe. If you are unsure, ask the nurse."],["li","Travay prensipal ou se ede rezidan yo ak aktivite lavi chak jou (ADL) epi rapòte bay enfimyè a nenpòt chanjman nan eta yon rezidan.","Your main job is to help residents with activities of daily living (ADLs) and to report any change in a resident's condition to the nurse."],["li","Swiv plan swen an. Si w panse yon bagay ladan l ta dwe chanje, di enfimyè a. Pa chanje l poukont ou.","Follow the care plan. If you think something in it should change, tell the nurse. Do not change it yourself."],["li","Règ fòmasyon federal yo bay lis konpetans swen pèsonèl yon asistan enfimyè: benyen, swen kò (tankou swen bouch), abiye, twalèt, ak ede moun nan manje ak bwè.","Federal training rules list the personal care skills of a nurse aide: bathing, grooming (including mouth care), dressing, toileting, and help with eating and drinking."],["li","Medikaman: nan Massachusetts, se sèlman yon CNA ki gen sètifika Asistan Medikaman (Certified Medication Aide) ki ka bay medikaman, sèlman kèk kalite, epi sèlman anba siveyans. Si w pa gen sètifika sa a, pa bay okenn medikaman.","Medications: in Massachusetts, only a CNA who has also earned Certified Medication Aide certification may give medications, only certain kinds, and only under supervision. Without that certification, do not give any medication."],["li","Rapòte chanjman bay enfimyè a san reta. Rapò fèt nan kòmansman ak nan fen chak ekip, epi chak fwa gen yon chanjman enpòtan.","Report changes to the nurse in a timely way. Reports happen at the start and end of every shift, and any time there is an important change."]]},{"h":["Devwa legal ak etik","Legal and ethical duties"],"src":["S1","S25","S26","S27"],"b":[["li","Kenbe tout enfòmasyon rezidan yo konfidansyèl (HIPAA), ansanm ak plan swen, dosye ak rapò chanjman ekip.","Keep all resident information confidential (HIPAA), including care plans, records and shift reports."],["li","Pa aksepte kado ni pouboire nan men rezidan yo oswa fanmi yo.","Do not accept gifts or tips from residents or their families."],["li","Lalwa oblije w rapòte: rapòte nenpòt siy abi oswa neglijans bay enfimyè a, epi rete ak rezidan an jiskaske pa gen lòt danje.","You are a mandated reporter: report any sign of abuse or neglect to the nurse, and stay with the resident until no further harm can happen."],["li","Si yon rezidan di w li sibi abi, rapòte l menm si rezidan an konfonn.","If a resident tells you about abuse, report it even if the resident is confused."],["li","Dosye a konfidansyèl: se sèlman moun ki dirèkteman nan swen rezidan an ki ka wè l. Si yon manm fanmi mande wè l, voye demann lan bay enfimyè a. Rezidan an gen dwa wè pwòp dosye pa l.","The chart is confidential: only people directly involved in the resident's care may see it. If a family member asks to see it, refer the request to the nurse. The resident has the right to see their own records."],["li","Pa poste anyen sou rezidan yo ni pataje foto yo sou rezo sosyal. Règ federal yo konte foto oswa anrejistreman ki imilye oswa ki rabese yon rezidan kòm abi mantal.","Do not post about residents or share their photos on social media. Federal rules count photos or recordings that demean or humiliate a resident as mental abuse."]]},{"h":["Kenbe sètifika w","Staying certified"],"src":["S21","S22"],"b":[["li","Yon etablisman pa ka fè w travay kòm asistan enfimyè plis pase 4 mwa si w poko fini yon pwogram fòmasyon ak evalyasyon ki apwouve.","A facility may not use you as a nurse aide for more than 4 months unless you completed an approved training and competency program."],["li","Ou bezwen omwen 12 èdtan fòmasyon kontinyèl chak ane, ansanm ak swen moun ki gen demans ak prevansyon abi.","You need at least 12 hours of in-service training every year, including dementia care and abuse prevention."],["li","Si w pase 24 mwa youn dèyè lòt san travay peye nan swen, ou dwe fè yon nouvo pwogram fòmasyon ak evalyasyon.","If you go 24 months in a row without paid nursing work, you must complete a new training and competency program."]]},{"h":["Pale ak rezidan yo","Talking with residents"],"src":["S1","S24","S25"],"b":[["li","Jès kò ak ton vwa w ka di plis pase pawòl ou.","Body language and tone of voice can say more than your words."],["li","Sèvi ak mo senp. Evite mo medikal rezidan an ka pa konnen.","Use plain words. Avoid medical terms the resident may not know."],["li","Bay rezidan an tout atansyon w. Diminye bri: fèmen pòt la oswa bese televizyon an, si l dakò.","Give the resident your full attention. Reduce noise: close the door or turn down the TV, with their permission."],["li","Pou yon moun ki konfonn, ba l yon chwa senp: «Soup oswa sandwich?» olye «Kisa w vle pou manje midi?»","For a person who is confused, offer a simple choice: \"Soup or a sandwich?\" instead of \"What do you want for lunch?\""],["li","Anvan nenpòt swen, eksplike sa w pral fè, pou rezidan an ka poze kesyon oswa di non. Rezidan yo gen dwa refize swen.","Before any care, explain what you will do, so the resident can ask questions or say no. Residents have the right to refuse care."],["li","Si yon rezidan fache, koute l san kritike, pa defann tèt ou, epi kenbe chanm nan kalm e trankil.","If a resident is angry, listen without criticizing, do not get defensive, and keep the room calm and quiet."],["li","Si yon rezidan mande w yon bagay ou pa ka reponn, tankou kesyon sou dyagnostik li, di enfimyè a pou yon moun ka swiv sa.","If a resident asks something you cannot answer, such as questions about their diagnosis, tell the nurse so someone can follow up."],["li","Afazi fè l difisil pou moun nan pale oswa konprann mo. Sèvi ak fraz kout e senp, bay anpil tan, kite moun nan lonje dwèt oswa fè jès, epi pa korije jan l pale.","Aphasia makes it hard to speak or understand words. Use short, simple sentences, give plenty of time, let the person point or gesture, and do not correct their speech."],["li","Aparèy pou tande: ede rezidan an mete yo anvan w pale, epi gade l an fas. Moun ki pa wè byen: di kiyès ou ye lè w ap antre nan chanm nan.","Hearing aids: help the resident put them in before you talk, then face them. Low vision: say who you are as you enter the room."]]}],"terms":[["scope of practice","limit travay ou"],["delegation","delegasyon"],["mandated reporter","moun lalwa oblije rapòte"],["in-service training","fòmasyon kontinyèl"],["nonverbal communication","kominikasyon san pawòl"]],"qs":[["n201",2,["delegation","delegasyon"],["Anvan w aksepte yon nouvo travay nan men enfimyè a, kisa pou w tcheke?","Sèlman si w gen tan","Si yon lòt asistan vle fè l","Limit travay ou, siveyans, sekirite ak materyèl","Si fanmi rezidan an dakò","Tcheke 4 «S» yo: limit travay ou, siveyans, sekirite ak materyèl. Si youn ladan yo manke, pale ak enfimyè a anvan."],["Before you accept a new task from the nurse, what should you check?","Only whether you have time","Whether another aide wants to do it","Scope, supervision, safety and supplies","Whether the resident's family agrees","Check the 4 S's: Scope, Supervision, Safety and Supplies. If any of them is missing, talk to the nurse first."]]],"check":["n201","n202","n203","n204","n205"]},{"ch":3,"bp":["Egzamen ekri MA: Sante mantal (4 kesyon sou 60) ak Swen moun ki gen pwoblèm memwa oswa sans (3).","MA written exam: Mental Health (4 of 60 questions) and Care Impaired (3)."],"title":["Sante mantal ak demans","Mental health and dementia"],"src":["S1","S23"],"sections":[{"h":["Depresyon ak enkyetid","Depression and anxiety"],"src":["S1","S23"],"b":[["li","Siy depresyon: moral ki tris, chimerik oswa vid, pa enterese ankò nan bagay moun nan te renmen, pa dòmi byen, chanjman nan apeti oswa pwa, fatig, dekourajman, ak pa okipe pwòpte l.","Signs of depression: a sad, irritable or empty mood, loss of interest in things the person enjoyed, poor sleep, changes in appetite or weight, tiredness, hopelessness, and poor hygiene."],["li","Rapòte chanjman nan moral bay enfimyè a. Si yon rezidan pale de mouri oswa fè tèt li mal, di enfimyè a touswit.","Report changes in mood or outlook to the nurse. If a resident talks about dying or hurting themselves, tell the nurse right away."],["li","Enkyetid ka lakòz ajitasyon, chimerik, misk ki rèd ak move dòmi. Yon atak panik se yon gwo laperèz ki rive toudenkou, souvan ak swe, tranble ak souf kout.","Anxiety can cause restlessness, irritability, tense muscles and poor sleep. A panic attack is sudden, intense fear, often with sweating, trembling and shortness of breath."],["li","Bay rezidan an tan pou l pale, kenbe menm woutin yo, epi pa pran konpòtman yo pou tèt ou.","Allow time for the resident to talk, keep routines predictable, and do not take behaviors personally."],["li","Lè yon rezidan pale sou santiman tristès oswa dezespwa, koute l epi kite l pale.","When a resident shares sad or hopeless feelings, listen and let them talk."],["li","Remake epi felisite efò yon rezidan ki deprime fè pou l patisipe nan swen li oswa pou l pase tan ak lòt moun.","Notice and praise a depressed resident's efforts to take part in their care or to spend time with others."],["li","Si yon rezidan pè oswa fache pandan swen an, kanpe. Pale dousman ak yon vwa ba, eksplike chak etap, epi pran yon poz si sa nesesè.","If a resident becomes frightened or upset during care, stop. Speak slowly in a soft voice, explain each step, and take a break if needed."],["li","Si yon rezidan ajite epi l refize swen, kenbe tout moun an sekirite epi fè sèlman sa ki vrèman nesesè kounye a. Eseye vire atansyon l sou yon lòt aktivite, epi eseye swen an ankò pita.","If a resident becomes agitated and refuses care, keep everyone safe and do only what is truly needed right now. Try to redirect them to another activity, and try the care again later."]]},{"h":["Sa pou w konnen sou demans","Dementia basics"],"src":["S1"],"b":[["li","Maladi Alzheimer se kalite demans ki pi komen. Pa gen gerizon.","Alzheimer's disease is the most common type of dementia. There is no cure."],["li","Konpòtman yo se siy maladi a, moun nan pa fè yo espre. Pa pran yo pou tèt ou.","Behaviors are symptoms of the disease, not done on purpose. Do not take them personally."],["li","Ajitasyon ki fèk parèt oswa ki vin pi grav ka soti nan doulè, yon enfeksyon tankou enfeksyon nan pipi, grangou, swaf, fatig, bri oswa twòp kesyon. Chèche kòz la epi rapòte l.","New or worse agitation can come from pain, an infection such as a UTI, hunger, thirst, tiredness, noise or too many questions. Look for the cause and report it."]]},{"h":["Pale ak yon moun ki gen demans","Communicating with a person with dementia"],"src":["S1"],"b":[["li","Sèvi ak mo senp, bay youn oswa de chwa, epi bay tan pou l reponn. Montre sa w vle di ak men w.","Use simple words, offer one or two choices, and give time to answer. Show or gesture what you mean."],["li","Validasyon: aksepte reyalite moun nan ap viv la. Pa diskite ni eseye korije l. Reponn a santiman l, apre sa vire atansyon l dousman.","Validation: accept the reality the person is living in. Do not argue or try to correct them. Respond to the feeling, then gently redirect."],["li","Si moun nan wè oswa tande bagay ki pa la, pa diskite. Rasire l, chanje lide l, epi di enfimyè a.","If the person sees or hears things that are not there, do not argue. Reassure them, distract them, and tell the nurse."]]},{"h":["Konfizyon aswè ak moun ki mache san rete","Sundowning and wandering"],"src":["S1"],"b":[["li","Konfizyon aswè (sundowning) se ajitasyon oswa konfizyon ki kòmanse oswa ki vin pi grav nan apremidi ak aswè, lè limyè jou a ap bese.","Sundowning is restlessness, agitation or confusion that starts or gets worse in the late afternoon and evening, as daylight fades."],["li","Pou ede: limyè jou nan maten, aswè trankil, fèmen rido yo lè solèy ap kouche, mwens bri ak mwens vizitè, epi pa gen kafeyin ta nan jounen an.","To help: daylight in the morning, quiet early evenings, close the curtains at dusk, less noise and fewer visitors, and no caffeine late in the day."],["li","Moun nan mache san rete lè l pa konn kote l ye. Pou diminye risk la: fè egzèsis regilye ak ti travay senp tankou pliye sèvyèt. Plan swen an ka gen yon braslè alam.","Wandering happens when the person is confused about where they are. To lower the risk: regular exercise and simple tasks such as folding towels. A wander alarm bracelet may be in the care plan."]]}],"terms":[["depression","depresyon"],["anxiety","enkyetid"],["dementia","demans"],["validation","validasyon"],["redirect","vire atansyon"],["sundowning","konfizyon aswè"],["wandering","mache san rete"],["hallucination","alisinasyon"]],"qs":[["n301",3,["depression","depresyon"],["Kiyès nan sa yo ki ka yon siy depresyon nan yon rezidan?","Mande yon dezyèm plat nan manje aswè","Patisipe nan tout aktivite gwoup","Pale anpil ak vizitè","Pa enterese ankò nan bagay li te konn renmen","Pa enterese ankò, chanjman nan dòmi ak apeti, fatig ak dekourajman ka siy depresyon. Rapòte yo bay enfimyè a."],["Which of these can be a sign of depression in a resident?","Asking for a second helping at dinner","Joining every group activity","Talking a lot with visitors","Losing interest in things they used to enjoy","Loss of interest, changes in sleep and appetite, tiredness and hopelessness can be signs of depression. Report them to the nurse."]]],"check":["n301","n302","n303","n304","n305"]},{"ch":4,"bp":["Egzamen ekri MA: Maladi yo (7 kesyon sou 60).","MA written exam: Disease Process (7 of 60 questions)."],"title":["Maladi ki komen","Common diseases"],"src":["S1"],"sections":[{"h":["Dyabèt","Diabetes"],"src":["S1"],"b":[["li","Sik ba: konfizyon oswa chimerik, tranble, po frèt ak mouye, swe, grangou, enkyetid. Rapòte l bay enfimyè a touswit.","Low blood sugar: confusion or irritability, shakiness, cold clammy skin, sweating, hunger, anxiety. Report it to the nurse immediately."],["li","Sik wo: pipi souvan, plis swaf ak grangou, souf ki gen sant fwi, po cho ak sèk, respire vit ak fon. Rapòte l bay enfimyè a touswit.","High blood sugar: frequent urination, more thirst and hunger, fruity breath, warm dry skin, fast deep breathing. Report it to the nurse immediately."],["li","Tcheke pye yo chak jou, ansanm ak anba pye ak ant zòtèy. Pa koupe zong yon rezidan ki gen dyabèt.","Check the feet every day, including the soles and between the toes. Do not trim the nails of a resident with diabetes."]]},{"h":["Kè fèb (ensifizans kadyak)","Heart failure"],"src":["S1"],"b":[["li","Nan ensifizans kadyak, misk kè a twò fèb pou l ponpe ase san.","In heart failure, the heart muscle is too weak to pump enough blood."],["li","Rapòte anflamasyon ki ap ogmante, souf kout, po ki vin ble, oswa pwa ki monte vit (plis pase 2 a 3 liv nan 24 èdtan).","Report increasing swelling, shortness of breath, bluish skin, or rapid weight gain (more than 2 to 3 pounds in 24 hours)."],["li","Peze rezidan an jan plan swen an di, swiv restriksyon likid, epi mezire sa k antre ak sa k soti.","Weigh the resident as the care plan says, follow any fluid restriction, and measure intake and output."]]},{"h":["Maladi poumon kwonik (COPD)","COPD"],"src":["S1"],"b":[["li","COPD se yon enflamasyon nan poumon ki dire lontan, souvan akoz sigarèt.","COPD is long-term inflammation of the lungs, often caused by smoking."],["li","Rapòte souf kout, difikilte pou respire, toudi, konfizyon oswa koulè ble touswit.","Report shortness of breath, labored breathing, dizziness, confusion or blue color right away."],["li","Ankouraje oksijèn sèlman jan yo preskri l. Pa chanje reglaj oksijèn nan poukont ou.","Encourage oxygen only as prescribed. Do not change oxygen settings yourself."]]},{"h":["Maladi Parkinson","Parkinson's disease"],"src":["S1"],"b":[["li","Parkinson lakòz mouvman ki dousman, move kowòdinasyon ak ekilib, tranbleman ak difikilte pou pale.","Parkinson's causes slow movement, poor coordination and balance, tremors and trouble speaking."],["li","Veye tonbe, kenbe aparèy pou mache nan rive men l, bay plis tan pou swen chak jou, epi rapòte chanjman nan fòs oswa jan l mache.","Watch for falls, keep walking aids within reach, allow extra time for daily care, and report changes in strength or walking."]]},{"h":["Atrit","Arthritis"],"src":["S1"],"b":[["li","Atrit (osteoarthritis) se enflamasyon jwenti akoz plizyè ane itilizasyon.","Osteoarthritis is joint inflammation from years of wear and tear."],["li","Mezi konfò nan plan swen an ka gen chalè, glas oswa chanje pozisyon. Ankouraje rezidan an rete aktif otan l kapab pou kenbe mouvman jwenti l.","Comfort measures from the care plan may include heat, ice or repositioning. Encourage the resident to stay as active as possible to keep range of motion."]]}],"terms":[["high blood sugar (hyperglycemia)","sik wo"],["heart failure","ensifizans kadyak"],["edema","anflamasyon (edèm)"],["COPD","COPD"],["tremor","tranbleman"],["arthritis","atrit"]],"qs":[["n401",2,["high blood sugar (hyperglycemia)","sik wo"],["Yon rezidan ki gen dyabèt swaf anpil, l ap pipi souvan, epi souf li gen yon sant fwi. Kisa sa ka ye?","Sik ki ba nan san; ba l ji epi tann","Yon reyaksyon nòmal apre yon gwo dine","Sik wo; rapòte l touswit","Yon grip k ap vini","Pipi souvan, swaf, souf ak sant fwi, po cho ak sèk ak respire vit ak fon se siy sik wo. Rapòte yo bay enfimyè a touswit."],["A resident with diabetes is very thirsty, urinating often, and has a fruity smell on his breath. What may this be?","Low blood sugar; give juice and wait","A normal reaction to a big dinner","High blood sugar; report it immediately","A cold coming on","Frequent urination, thirst, fruity breath, warm dry skin and fast deep breathing are signs of high blood sugar. Report them to the nurse immediately."]]],"check":["n401","n402","n403","n404","n405"]},{"ch":5,"bp":["Egzamen ekri MA: yon pati nan Dwa rezidan yo (6 kesyon sou 60) ak Sekirite (6).","MA written exam: part of Resident Rights (6 of 60 questions) and Safety (6)."],"title":["Mare moun ak lòt solisyon","Restraints and restraint alternatives"],"src":["S1","S20"],"sections":[{"h":["Sa sa ye mare yon moun","What a restraint is"],"src":["S1"],"b":[["p","Mare yon moun (restraint) se nenpòt aparèy, metòd oswa pwosesis ki anpeche moun nan bouje lib.","A restraint is any device, method or process used to restrict a person's freedom of movement."],["li","Egzanp: ba kabann ki leve pou anpeche rezidan an soti nan kabann, fren chèz woulant oswa senti rezidan an pa ka lage, yon plato sou janm ki anpeche l bouje.","Examples: side rails raised to stop the resident from getting out of bed, wheelchair brakes or a seat belt the resident cannot release, a lap tray that keeps them from moving."],["li","Mare ak medikaman (chemical restraint) se yon medikaman yo sèvi pou kontwole konpòtman ki pa tretman nòmal pou kondisyon moun nan.","A chemical restraint is a drug used to control behavior that is not the standard treatment for the person's condition."]]},{"h":["Règ yo","The rules"],"src":["S20","S1"],"b":[["li","Rezidan yo gen dwa pou yo pa mare yo pou pinisyon oswa pou fasilite travay anplwaye yo, lè sa pa nesesè pou trete yon siy medikal.","Residents have the right to be free from restraints used for discipline or staff convenience, and not needed to treat a medical symptom."],["li","Swen san mare moun se règ la. Mare yon moun se dènye solisyon, epi li bezwen yon lòd doktè. Swiv plan swen an ak règ etablisman an egzakteman.","Restraint-free care is the standard. A restraint is a last resort and needs a provider's order. Follow the care plan and facility policy exactly."],["li","Pa janm kite yon senti mache sou moun nan apre yon transfè pou fasilite travay ou.","Never leave a gait belt on after a transfer for convenience."]]},{"h":["Lè gen lòd pou mare yon moun","When a restraint is ordered"],"src":["S1"],"b":[["li","Tcheke rezidan an souvan, jan règ etablisman an di (pi bon pratik la se omwen chak 15 minit).","Check the resident often, as facility policy says (best practice is at least every 15 minutes)."],["li","Retire restraint lan chak 1 a 2 èdtan pou egzèsis mouvman ak tcheke po a. Ofri manje, likid ak twalèt, epi ekri sa.","Remove the restraint every 1 to 2 hours for range of motion and a skin check. Offer food, fluids and toileting, and document it."],["li","Mare restraint lan nan kabann nan sèlman ak yon ne ki demare vit.","Tie a restraint to the bed only with a quick-release knot."],["li","Danje mare moun: tonbe, toufe, blesi presyon, misk ki vin fèb, laperèz ak wont.","Risks of restraints: falls, strangulation, pressure injuries, weak muscles, fear and humiliation."]]},{"h":["Lòt solisyon olye mare moun","Alternatives to restraints"],"src":["S1"],"b":[["li","Anvan tout bagay, chèche kòz konpòtman an: doulè, grangou, swaf oswa bezwen al nan twalèt.","First look for the cause of the behavior: pain, hunger, thirst or needing the toilet."],["li","Pou yon rezidan ki toujou ap eseye leve poukont li: ofri l al nan twalèt souvan, ede l mache, epi ba l yon bagay pou l fè. Plan swen an ka gen yon alam; asire w li mache.","For a resident who keeps trying to get up alone: offer toileting often, help them walk, and give them something to do. An alarm may be in the care plan; make sure it works."],["li","Apre swen, kite kabann nan nan pozisyon ki pi ba a, ak wou yo bloke, epi bouton apèl la kote rezidan an ka rive jwenn li.","After care, leave the bed in its lowest position with the wheels locked, and the call light within reach."]]}],"terms":[["restraint","mare moun (restraint)"],["chemical restraint","mare ak medikaman"],["quick-release knot","ne ki demare vit"],["restraint alternative","lòt solisyon olye mare"]],"qs":[["n501",3,["restraint","mare moun (restraint)"],["Kiyès nan sa yo ki se yon fason pou mare moun (restraint)?","Yon walker li sèvi lè l vle mache nan koridò a","Linèt ak aparèy pou tande li mete pou kont li","Yon limyè pou rele ki tache kote men l rive nan kabann","Yon plato sou janm rezidan an pa ka retire ki kenbe l nan chèz la","Nenpòt bagay ki anpeche yon moun bouje lib epi l pa ka retire l se yon restraint, tankou yon plato sou janm, yon senti oswa fren li pa ka lage."],["Which of these is a restraint?","A walker she uses whenever she wants to walk in the hall","Glasses and a hearing aid she puts on herself","A call light clipped within her reach in bed","A lap tray the resident cannot remove that keeps her in the chair","Anything that restricts a person's freedom of movement and that they cannot remove is a restraint, such as a lap tray, a seat belt or brakes they cannot release."]]],"check":["n501","n502","n503","n504","n505"]},{"ch":6,"bp":["Egzamen ekri MA: Kolekte done (2 kesyon sou 60); egzamen pratik la ka mande w mezire pipi.","MA written exam: Data Collection (2 of 60 questions); the skills test can include measuring urine output."],"title":["Mezire ak ekri","Measuring and recording"],"src":["S1"],"sections":[{"h":["Likid moun nan bwè","Fluid intake"],"src":["S1"],"b":[["li","Yo ekri likid an mililit (mL). Miltipliye ons yo pa 30: 1 ons = 30 mL.","Fluids are recorded in milliliters (mL). Multiply ounces by 30: 1 ounce = 30 mL."],["li","Kantite ki komen: 4 ons = 120 mL, 6 ons = 180 mL, 1 tas (8 ons) = 240 mL.","Common sizes: 4 oz = 120 mL, 6 oz = 180 mL, 1 cup (8 oz) = 240 mL."],["li","Tout sa ki fonn nan tanperati chanm oswa nan kò a konte kòm likid: bouyon, ti mòso glas, krèm glase, fresko, jelatin. Soup konte kòm manje.","Anything that melts at room or body temperature counts as fluid: broth, ice chips, ice cream, popsicles, gelatin. Soup is recorded as food."],["li","Yo estime manje moun nan manje pa 25% ki pi pre a.","Food intake is estimated to the nearest 25%."]]},{"h":["Sa k soti","Output"],"src":["S1"],"b":[["li","Pipi se sa yo mezire pi souvan. Yo mezire tou likid ki nan yon aparèy drenaj.","Urine is the output measured most often. Drainage in a drainage device is also measured."],["li","Yo fè total sa k antre ak sa k soti pou 24 èdtan. Total sa k antre dwe pre total sa k soti.","Intake and output are totaled over 24 hours. Total intake should be close to total output."]]},{"h":["Pwa","Weight"],"src":["S1"],"b":[["li","Sèvi ak menm balans lan, menm lè nan jounen an, anvan rezidan an manje oswa bwè, ak prèske menm rad.","Use the same scale, at the same time of day, before the resident eats or drinks, with about the same clothing."],["li","Nan chèz woulant: peze chèz la anvan, apre sa peze rezidan an nan chèz la, epi retire pwa chèz la.","In a wheelchair: weigh the chair first, then the resident in the chair, and subtract the chair's weight."],["li","Rapòte yon chanjman 3 liv nan 24 èdtan oswa 5 liv nan yon semèn bay enfimyè a touswit.","Report a change of 3 pounds in 24 hours or 5 pounds in a week to the nurse right away."]]},{"h":["Wotè","Height"],"src":["S1"],"b":[["li","Yo konn mezire wotè lè rezidan an fèk antre. Yon rezidan ki ka kanpe, yo mezire l kanpe.","Height is usually measured at admission. A resident who can stand is measured standing."],["li","Si rezidan an pa ka kanpe, mezire l kouche nan kabann ak yon mèt riban.","If the resident cannot stand, measure them lying in bed with a tape measure."]]}],"terms":[["intake and output (I&O)","sa k antre ak sa k soti"],["milliliter (mL)","mililit (mL)"],["ounce (oz)","ons"],["graduate (measuring container)","veso pou mezire"],["scale","balans"]],"qs":[["n601",2,["milliliter (mL)","mililit (mL)"],["Yon rezidan bwè yon vè ji 6 ons. Konbyen mL pou w ekri?","60 mL","120 mL","180 mL","240 mL","1 ons = 30 mL, kidonk 6 ons x 30 = 180 mL."],["A resident drinks a 6-ounce glass of juice. How many mL do you record?","60 mL","120 mL","180 mL","240 mL","1 ounce = 30 mL, so 6 ounces x 30 = 180 mL."]]],"check":["n601","n602","n603","n604","n605"]},{"ch":7,"bp":["Egzamen ekri MA: yon pati nan Sante mantal (4 kesyon sou 60) ak Konpetans debaz swen enfimyè (8).","MA written exam: part of Mental Health (4 of 60 questions) and Basic Nursing Skills (8)."],"title":["Swen nan fen lavi","End-of-life care"],"src":["S1"],"sections":[{"h":["Lapenn","Grief"],"src":["S1"],"b":[["li","Etap lapenn yo se: refize, kòlè, negosye, depresyon ak aksepte. Moun ka pase nan yo nan nenpòt lòd, repase nan yo oswa sote kèk.","The stages of grief are denial, anger, bargaining, depression and acceptance. People may go through them in any order, repeat them or skip some."],["li","Kòlè souvan soti nan pèdi kontwòl, epi l ka tonbe sou anplwaye yo. Pa pran l pou tèt ou. Kite moun nan pale, men kenbe limit ak respè.","Anger often comes from losing control and may be aimed at staff. Do not take it personally. Let the person vent, while keeping respectful limits."]]},{"h":["Ospis ak volonte davans","Hospice and advance directives"],"src":["S1"],"b":[["li","Swen ospis se pou yon moun ki gen yon maladi ki p ap geri. Li konsantre sou konfò, pa sou gerizon, epi li pa fè moun nan mouri pi vit.","Hospice care is for a person with a terminal illness. It focuses on comfort, not cure, and does not hasten death."],["li","Yon lòd DNR (pa reyanime) konsène sèlman CPR. Tout lòt swen kontinye.","A DNR (do not resuscitate) order covers only CPR. All other care continues."],["li","Sipòte volonte rezidan an. Si w wè yon konfli sou sa, di enfimyè a.","Support the resident's wishes. If you see a conflict about them, tell the nurse."]]},{"h":["Swen konfò","Comfort care"],"src":["S1"],"b":[["li","Di enfimyè a 10 a 15 minit anvan w bay swen, pou yo ka tcheke epi trete doulè a anvan.","Tell the nurse 10 to 15 minutes before you give care, so pain can be checked and treated first."],["li","Swen bouch: yon ti baton koton mouye ak krèm pou po bouch souvan. Chanje pozisyon souvan pou pwoteje po a, jan plan swen an di.","Mouth care: a moist swab and lip balm often. Reposition often to protect the skin, as the care plan says."],["li","Kenbe chanm nan trankil, ak limyè moun nan santi l alèz, san sant fò.","Keep the room quiet, with lighting the person finds comfortable and no strong scents."]]},{"h":["Lè lanmò pre","When death is near"],"src":["S1"],"b":[["li","Siy yo: men ak pye ki frèt, ki ka pal oswa ble; po vyolèt ak tach, souvan sou janm ak pye; respirasyon ki pa regilye ak poz; bri nan souf la; mwens manje, bwè ak pipi.","Signs: cool hands and feet that may look pale or bluish; purple, mottled skin, often on the legs and feet; irregular breathing with pauses; rattling breath sounds; less intake and output."],["li","Tande se dènye sans ki rete. Eksplike chak swen, kontinye pale ak moun nan tankou l konprann, epi fè atansyon ak sa w di bò kote l.","Hearing is the last sense to fail. Explain each task, keep talking to the person as if they understand, and be careful what you say nearby."]]}],"terms":[["hospice","ospis"],["do not resuscitate (DNR)","pa reyanime (DNR)"],["mottling","po ak tach"],["grief","lapenn"],["comfort care","swen konfò"]],"qs":[["n701",2,["grief","lapenn"],["Kisa ki vre sou etap lapenn yo?","Tout moun pase nan yo nan menm lòd","Yo toujou fini nan yon semèn","Yon moun ka pase nan yo nan nenpòt lòd oswa repase nan yo","Se fanmi an sèlman ki pase nan yo","Refize, kòlè, negosye, depresyon ak aksepte ka vini nan nenpòt lòd, repete, oswa pa vini ditou."],["What is true about the stages of grief?","Everyone goes through them in the same order","They always end in one week","A person may go through them in any order or repeat them","Only the family goes through them","Denial, anger, bargaining, depression and acceptance can come in any order, repeat, or be skipped."]]],"check":["n701","n702","n703","n704","n705"]}];
